"use client";

import { useState } from "react";
import { SpaceBackground } from "@/components/ui/space-background";
import { Logo } from "@/components/ui/logo";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { AccessRequests } from "@/components/admin/access-requests";
import { TeacherInviteCodes } from "@/components/admin/teacher-invite-codes";
import { FirestoreExplorer } from "@/components/admin/firestore-explorer";
import { GlobalAnalytics } from "@/components/admin/global-analytics";
import { TooltipProvider } from "@/components/ui/tooltip";
import { ShieldCheck, Eye, EyeOff, Lock, Database, BarChart3 } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

export default function AdminPage() {
  const [secret, setSecret] = useState("");
  const [showSecret, setShowSecret] = useState(false);
  const [authed, setAuthed] = useState(false);
  const [checking, setChecking] = useState(false);
  const [error, setError] = useState("");

  const [activeTab, setActiveTab] = useState<"access" | "database" | "analytics">("access");

  const handleUnlock = async () => {
    if (!secret.trim()) {
      setError("Enter the admin secret.");
      return;
    }
    setChecking(true);
    setError("");
    try {
      // Verify the secret by attempting a list call
      const res = await fetch("/api/auth/teacher-code", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-admin-secret": secret.trim(),
        },
        body: JSON.stringify({ action: "list" }),
      });
      if (res.status === 401) {
        setError("Invalid admin secret.");
        return;
      }
      setAuthed(true);
    } catch {
      setError("Network error. Please try again.");
    } finally {
      setChecking(false);
    }
  };

  if (!authed) {
    return (
      <div className="min-h-screen flex items-center justify-center p-4 relative">
        <SpaceBackground />
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          className="w-full max-w-sm"
        >
          <Card>
            <CardHeader className="text-center">
              <div className="flex justify-center mb-3">
                <div className="h-12 w-12 rounded-xl bg-primary/10 flex items-center justify-center">
                  <ShieldCheck className="h-6 w-6 text-primary" />
                </div>
              </div>
              <CardTitle className="text-xl">Admin Access</CardTitle>
              <CardDescription>Enter the admin secret to continue.</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="space-y-2">
                <Label htmlFor="admin-secret">Admin Secret</Label>
                <div className="relative">
                  <Input
                    id="admin-secret"
                    type={showSecret ? "text" : "password"}
                    placeholder="••••••••••••"
                    value={secret}
                    onChange={(e) => setSecret(e.target.value)}
                    onKeyDown={(e) => e.key === "Enter" && !checking && handleUnlock()}
                    className="pr-10"
                    autoFocus
                  />
                  <button
                    type="button"
                    onClick={() => setShowSecret(!showSecret)}
                    className="absolute inset-y-0 right-0 pr-3 flex items-center text-muted-foreground hover:text-foreground transition-colors"
                  >
                    {showSecret ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                  </button>
                </div>
              </div>
              {error && (
                <p className="text-sm text-destructive bg-destructive/10 border border-destructive/20 rounded-md px-3 py-2">
                  {error}
                </p>
              )}
              <Button className="w-full" onClick={handleUnlock} disabled={checking}>
                {checking ? "Verifying…" : "Unlock"}
              </Button>
            </CardContent>
          </Card>
        </motion.div>
      </div>
    );
  }

  return (
    <div className="min-h-screen w-full relative flex flex-col md:flex-row bg-background">
      <SpaceBackground />

      {/* Sidebar */}
      <motion.aside 
        initial={{ x: -20, opacity: 0 }}
        animate={{ x: 0, opacity: 1 }}
        className="w-full md:w-64 border-b md:border-b-0 md:border-r border-border/40 relative z-20 bg-background/60 backdrop-blur-xl flex flex-col h-auto md:h-screen sticky top-0"
      >
        <div className="p-6 flex items-center gap-3 border-b border-border/40">
          <Logo size={24} className="text-foreground" />
          <div>
            <h1 className="text-lg font-bold leading-tight">Admin</h1>
            <p className="text-xs text-muted-foreground">Scorpio Platform</p>
          </div>
        </div>

        <nav className="p-4 space-y-2 flex-1 overflow-y-auto">
          <div className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-2 px-2">
            Modules
          </div>
          <Button
            variant={activeTab === "access" ? "secondary" : "ghost"}
            className="w-full justify-start font-medium"
            onClick={() => setActiveTab("access")}
          >
            <Lock className="mr-2 h-4 w-4" />
            Access & Security
          </Button>
          <Button
            variant={activeTab === "analytics" ? "secondary" : "ghost"}
            className="w-full justify-start font-medium"
            onClick={() => setActiveTab("analytics")}
          >
            <BarChart3 className="mr-2 h-4 w-4" />
            Analytics & Insights
          </Button>
          <Button
            variant={activeTab === "database" ? "secondary" : "ghost"}
            className="w-full justify-start font-medium"
            onClick={() => setActiveTab("database")}
          >
            <Database className="mr-2 h-4 w-4" />
            Database Explorer
          </Button>
        </nav>

        <div className="p-4 border-t border-border/40 mt-auto">
          <Button 
            variant="outline" 
            className="w-full justify-start text-muted-foreground hover:text-foreground"
            onClick={() => setAuthed(false)}
          >
            Log Out
          </Button>
        </div>
      </motion.aside>

      {/* Main Content Area */}
      <main className="flex-1 min-w-0 relative z-10 p-6 md:p-10 h-[calc(100vh-80px)] md:h-screen overflow-y-auto">
        <TooltipProvider>
          <AnimatePresence mode="wait">
            {activeTab === "access" && (
              <motion.div
                key="access"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                transition={{ duration: 0.2 }}
                className="max-w-4xl mx-auto space-y-8"
              >
                <div>
                  <h2 className="text-2xl font-bold tracking-tight">Access & Security</h2>
                  <p className="text-muted-foreground">Manage waitlist access requests and teacher invite codes.</p>
                </div>

                <AccessRequests adminSecret={secret} />
                <TeacherInviteCodes adminSecret={secret} />
              </motion.div>
            )}

            {activeTab === "analytics" && (
              <motion.div
                key="analytics"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                transition={{ duration: 0.2 }}
                className="max-w-6xl mx-auto space-y-8"
              >
                <GlobalAnalytics />
              </motion.div>
            )}

            {activeTab === "database" && (
              <motion.div
                key="database"
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                transition={{ duration: 0.2 }}
                className="max-w-6xl mx-auto h-[80vh] flex flex-col space-y-4"
              >
                <div>
                  <h2 className="text-2xl font-bold tracking-tight">Database Explorer</h2>
                  <p className="text-muted-foreground">Query read-only platform data directly from Firestore.</p>
                </div>

                <div className="flex-1 min-h-0">
                  <FirestoreExplorer adminSecret={secret} />
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </TooltipProvider>
      </main>
    </div>
  );
}

"use client";

import { useState, useRef, useEffect, useCallback } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Send, ArrowRight, RefreshCw, CornerDownLeft } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { cn } from "@/lib/utils";
import { RaiseLogo } from "@/components/ui/raise-logo";
import { SiteHeader } from "@/components/landing/site-header";
import { SpaceBackground } from "@/components/ui/space-background";
import { MarkdownRenderer } from "@/components/markdown-renderer";
import Link from "next/link";

// ─── Types ─────────────────────────────────────────────────────────────────────

interface Message {
  id: string;
  role: "user" | "assistant";
  content: string;
  isStreaming?: boolean;
}

// ─── Starter Prompts ────────────────────────────────────────────────────────────

const STARTERS: { label: string; prompt: string; response: string }[] = [
  {
    label: "Incline acceleration",
    prompt: "A 5 kg block slides down a frictionless 30° incline. What is its acceleration?",
    response:
      "Before arriving at a number, let's build the correct physical picture.\n\n**Draw a free-body diagram.** Two forces act on this block: gravity ($\\vec{F}_g = mg$ downward) and the normal force ($\\vec{N}$, perpendicular to the surface). No friction — so those are the only two.\n\n**Decompose gravity along the incline's axes.** If the ramp makes angle $\\theta$ with the horizontal, the component of gravity *parallel* to the surface is\n\n$$F_{\\parallel} = mg\\sin\\theta$$\n\nand the component *perpendicular* to the surface (balanced by $N$) is\n\n$$F_{\\perp} = mg\\cos\\theta$$\n\n**Apply Newton's Second Law along the incline:**\n\n$$ma = mg\\sin\\theta \\implies a = g\\sin\\theta$$\n\nNow — *why* does mass cancel here? And what does that tell you about which objects would slide fastest on this ramp?",
  },
  {
    label: "Normal force misconception",
    prompt: "My teacher said the normal force always equals mg. Is that correct?",
    response:
      "That statement is true in one specific case — and false in most others. Catching this early will save you from a lot of incorrect free-body diagrams.\n\n**When $N = mg$:** A block on a flat horizontal surface in static equilibrium, with no vertical acceleration. The surface pushes up with exactly $mg$ to prevent the block from falling through.\n\n**When $N \\neq mg$:**\n\n- *Inclined surface:* The normal force is perpendicular to the ramp, so $N = mg\\cos\\theta$ — which is always *less* than $mg$ for $\\theta > 0$.\n- *Elevator accelerating upward:* Newton's second law gives $N - mg = ma$, so $N = m(g + a) > mg$.\n- *Object on a curved surface at speed $v$:* Centripetal acceleration modifies the equation further.\n\nThe general principle is: **the normal force is whatever value is required to satisfy Newton's Second Law in the direction perpendicular to the surface.**\n\nWith that in mind — on a 30° ramp, what is the correct expression for $N$?",
  },
  {
    label: "Newton's Third Law",
    prompt: "I don't understand Newton's Third Law. Can you explain it?",
    response:
      "Newton's Third Law states:\n\n> *For every force exerted by object A on object B, there is an equal and opposite force exerted by object B on object A.*\n\nMore compactly: $\\vec{F}_{AB} = -\\vec{F}_{BA}$.\n\n**The critical distinction students miss:** These two forces act on *different* objects. They never cancel each other — they can't, because cancellation only applies to forces on the *same* object.\n\n**A concrete example:** You push on a wall with force $\\vec{F} = 10\\,\\text{N}$ to the right. The wall pushes back on *you* with $10\\,\\text{N}$ to the left. The wall doesn't move because the *floor* provides an equal-and-opposite horizontal friction force on it — that's a separate pair.\n\nHere's a question to test your understanding: A horse pulls a cart. The cart pulls the horse backward with an equal and opposite force. If the forces are equal, why does the horse-cart system accelerate forward at all?",
  },
];

const LIMIT = 3;
const COUNT_KEY = "scorpio_ai_page_msg_count";
const VISITOR_KEY = "scorpio_ai_page_visitor_id";
const SESSION_MESSAGES_KEY = "scorpio_ai_session_messages";
const SESSION_QLEFT_KEY = "scorpio_ai_session_qleft";

function getOrCreateVisitorId(): string {
  if (typeof window === "undefined") return "";
  let id = localStorage.getItem(VISITOR_KEY);
  if (!id) {
    id = `v_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;
    localStorage.setItem(VISITOR_KEY, id);
  }
  return id;
}

function getLocalCount(): number {
  if (typeof window === "undefined") return 0;
  return parseInt(localStorage.getItem(COUNT_KEY) || "0", 10);
}

function incrementLocalCount() {
  if (typeof window === "undefined") return;
  localStorage.setItem(COUNT_KEY, String(getLocalCount() + 1));
}

function loadSessionMessages(): Message[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = sessionStorage.getItem(SESSION_MESSAGES_KEY);
    if (!raw) return [];
    const parsed: Message[] = JSON.parse(raw);
    return parsed.map((m) => ({ ...m, isStreaming: false }));
  } catch {
    return [];
  }
}

function saveSessionMessages(msgs: Message[]) {
  if (typeof window === "undefined") return;
  try {
    sessionStorage.setItem(
      SESSION_MESSAGES_KEY,
      JSON.stringify(msgs.map((m) => ({ ...m, isStreaming: false })))
    );
  } catch {}
}

function loadSessionQLeft(): number | null {
  if (typeof window === "undefined") return null;
  const raw = sessionStorage.getItem(SESSION_QLEFT_KEY);
  if (raw === null) return null;
  return parseInt(raw, 10);
}

function saveSessionQLeft(n: number) {
  if (typeof window === "undefined") return;
  sessionStorage.setItem(SESSION_QLEFT_KEY, String(n));
}

function clearSession() {
  if (typeof window === "undefined") return;
  sessionStorage.removeItem(SESSION_MESSAGES_KEY);
  sessionStorage.removeItem(SESSION_QLEFT_KEY);
  localStorage.setItem(COUNT_KEY, "0");
}

export default function AIPage() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState("");
  const [isTyping, setIsTyping] = useState(false);
  const [questionsLeft, setQuestionsLeft] = useState(LIMIT);
  const [visitorId, setVisitorId] = useState("");
  const [mounted, setMounted] = useState(false);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);

  useEffect(() => {
    setMounted(true);
    const id = getOrCreateVisitorId();
    setVisitorId(id);

    const sessionMsgs = loadSessionMessages();
    const sessionQLeft = loadSessionQLeft();

    if (sessionMsgs.length > 0) {
      setMessages(sessionMsgs);
    }

    if (sessionQLeft !== null) {
      setQuestionsLeft(sessionQLeft);
    } else {
      const used = getLocalCount();
      setQuestionsLeft(Math.max(0, LIMIT - used));
    }
  }, []);

  const scrollToBottom = useCallback(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, []);

  useEffect(scrollToBottom, [messages, isTyping, scrollToBottom]);

  const simulateStreaming = (fullText: string, messageId: string) => {
    const words = fullText.split(" ");
    let i = 0;
    let currentText = "";
    const interval = setInterval(() => {
      if (i < words.length) {
        currentText += (i === 0 ? "" : " ") + words[i];
        setMessages((prev) =>
          prev.map((m) => (m.id === messageId ? { ...m, content: currentText } : m))
        );
        i++;
        scrollToBottom();
      } else {
        clearInterval(interval);
        setMessages((prev) => {
          const next = prev.map((m) =>
            m.id === messageId ? { ...m, content: fullText, isStreaming: false } : m
          );
          saveSessionMessages(next);
          return next;
        });
      }
    }, 28);
  };

  const handleSend = useCallback(
    async (text: string, offlineResponse?: string) => {
      if (!text.trim() || questionsLeft <= 0 || isTyping) return;

      const newQ = questionsLeft - 1;
      setMessages((prev) => {
        const next = [...prev, { id: `u_${Date.now()}`, role: "user" as const, content: text }];
        saveSessionMessages(next);
        return next;
      });
      setInput("");
      setIsTyping(true);
      setQuestionsLeft(newQ);
      saveSessionQLeft(newQ);
      incrementLocalCount();

      if (offlineResponse) {
        setTimeout(() => {
          setIsTyping(false);
          const aid = `a_${Date.now()}`;
          setMessages((prev) => [
            ...prev,
            { id: aid, role: "assistant", content: "", isStreaming: true },
          ]);
          simulateStreaming(offlineResponse, aid);
        }, 500);
        return;
      }

      try {
        const res = await fetch("/api/chat/landing", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ message: text, visitorId }),
        });
        const data = await res.json();
        setIsTyping(false);
        const aid = `a_${Date.now()}`;
        setMessages((prev) => [
          ...prev,
          { id: aid, role: "assistant", content: "", isStreaming: true },
        ]);
        simulateStreaming(
          res.ok ? data.text : data?.error || "Something went wrong. Please try again.",
          aid
        );
      } catch {
        setIsTyping(false);
        setMessages((prev) => [
          ...prev,
          {
            id: `a_err_${Date.now()}`,
            role: "assistant",
            content: "Connection error. Please try again.",
          },
        ]);
      }
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [questionsLeft, isTyping, visitorId]
  );

  const reset = () => {
    clearSession();
    setMessages([]);
    setQuestionsLeft(LIMIT);
    setInput("");
    setTimeout(() => inputRef.current?.focus(), 80);
  };

  const isLimitReached = questionsLeft <= 0;
  const isEmpty = mounted && messages.length === 0;

  if (!mounted) return null;

  return (
    <div className="min-h-screen flex flex-col relative font-medium">
      <SpaceBackground />
      <SiteHeader />

      <div
        className="flex flex-col flex-1 mx-auto w-full max-w-[680px] px-5 relative z-10"
        style={{ paddingTop: "88px" }}
      >
        {/* ── Empty / Welcome State ─────────────────────────────────────── */}
        <AnimatePresence>
          {isEmpty && (
            <motion.div
              key="empty"
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -6 }}
              transition={{ duration: 0.35, ease: [0.22, 1, 0.36, 1] }}
              className="flex flex-col flex-1 justify-center pb-36"
            >
              {/* Identity */}
              <div className="flex items-center gap-2.5 mb-8">
                <div className="h-7 w-7 rounded-[7px] bg-primary flex items-center justify-center shadow-sm">
                  <RaiseLogo size={14} className="text-primary-foreground" />
                </div>
                <span className="text-[14px] font-semibold text-foreground">Raise</span>
                <span className="text-[11px] font-medium text-muted-foreground border border-border/80 rounded-md px-2 py-0.5 leading-none">
                  AI Learning Assistant
                </span>
              </div>

              {/* Heading */}
              <h1 className="text-[28px] sm:text-[34px] font-bold tracking-[-0.03em] text-foreground leading-[1.2] mb-3">
                Ask a physics question.
              </h1>
              <p className="text-[15px] text-muted-foreground leading-[1.7] mb-9 max-w-[500px]">
                Raise will guide you to the answer — it will not give it to you directly. This is the same approach used in partner physics classrooms.{" "}
                <span className="text-foreground font-medium">{questionsLeft} questions available.</span>
              </p>

              {/* Starters */}
              <div className="space-y-1.5">
                <p className="text-[11px] font-semibold uppercase tracking-[0.1em] text-muted-foreground/60 mb-3">
                  Example questions
                </p>
                {STARTERS.map((s, i) => (
                  <button
                    key={i}
                    onClick={() => handleSend(s.prompt, s.response)}
                    className="group w-full flex items-center justify-between gap-4 text-left px-4 py-3 rounded-xl border border-border/80 bg-card/20 hover:bg-muted/40 transition-all duration-150 cursor-pointer"
                  >
                    <div className="flex items-start gap-3 min-w-0">
                      <span className="text-[11px] font-bold uppercase tracking-widest text-muted-foreground/50 shrink-0 pt-[3px]">
                        {String(i + 1).padStart(2, "0")}
                      </span>
                      <span className="text-[13.5px] text-muted-foreground group-hover:text-foreground transition-colors leading-snug truncate">
                        {s.prompt}
                      </span>
                    </div>
                    <ArrowRight className="h-3.5 w-3.5 shrink-0 text-muted-foreground/30 group-hover:text-foreground group-hover:translate-x-0.5 transition-all" />
                  </button>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* ── Conversation ─────────────────────────────────────────────── */}
        {!isEmpty && (
          <div className="flex-1 py-10 space-y-8">
            {messages.map((m) => (
              <motion.div
                key={m.id}
                initial={{ opacity: 0, y: 8 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ duration: 0.25, ease: "easeOut" }}
              >
                {m.role === "user" ? (
                  <div className="flex justify-end">
                    <div className="max-w-[80%] sm:max-w-[75%] bg-primary rounded-2xl rounded-tr-sm px-4 py-3 text-[14.5px] leading-[1.65] text-primary-foreground font-medium shadow-sm">
                      {m.content}
                    </div>
                  </div>
                ) : (
                  <div className="flex gap-3 items-start">
                    <div className="h-6 w-6 rounded-[6px] bg-primary flex items-center justify-center shrink-0 mt-[2px] shadow-sm">
                      <RaiseLogo size={12} className="text-primary-foreground" />
                    </div>
                    <div className="flex-1 min-w-0 pt-[1px]">
                      <MarkdownRenderer
                        className={cn(
                          "text-[14.5px] leading-[1.75]",
                          "[&_.katex]:text-[0.95em]",
                          "[&_.katex-display]:my-3",
                          "[&_p]:text-foreground [&_p]:leading-[1.75] [&_p]:my-1",
                          "[&_strong]:font-semibold [&_strong]:text-foreground",
                          "[&_blockquote]:border-l-2 [&_blockquote]:border-border [&_blockquote]:pl-4 [&_blockquote]:text-muted-foreground [&_blockquote]:italic [&_blockquote]:my-3",
                          "[&_ul]:my-2 [&_ul]:space-y-1 [&_li]:text-foreground",
                          "[&_ol]:my-2 [&_ol]:space-y-1",
                          "[&_code]:text-[0.84em] [&_code]:bg-muted [&_code]:rounded [&_code]:px-1.5 [&_code]:py-0.5",
                          "[&_pre]:bg-muted [&_pre]:rounded-xl [&_pre]:p-4 [&_pre]:my-3 [&_pre]:overflow-x-auto",
                          m.isStreaming && "after:content-[''] after:inline-block after:w-[2px] after:h-[1em] after:bg-foreground/40 after:ml-0.5 after:align-middle after:animate-pulse"
                        )}
                        noProse
                      >
                        {m.content || " "}
                      </MarkdownRenderer>
                    </div>
                  </div>
                )}
              </motion.div>
            ))}

            {/* Typing dots */}
            {isTyping && (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                className="flex gap-3 items-center"
              >
                <div className="h-6 w-6 rounded-[6px] bg-primary flex items-center justify-center shrink-0">
                  <RaiseLogo size={12} className="text-primary-foreground" />
                </div>
                <div className="flex items-center gap-[5px]">
                  <span className="h-[5px] w-[5px] rounded-full bg-muted-foreground/40 animate-bounce" style={{ animationDelay: "0ms" }} />
                  <span className="h-[5px] w-[5px] rounded-full bg-muted-foreground/40 animate-bounce" style={{ animationDelay: "140ms" }} />
                  <span className="h-[5px] w-[5px] rounded-full bg-muted-foreground/40 animate-bounce" style={{ animationDelay: "280ms" }} />
                </div>
              </motion.div>
            )}

            {/* Limit wall */}
            <AnimatePresence>
              {isLimitReached && !isTyping && (
                <motion.div
                  initial={{ opacity: 0, y: 8 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="border border-border rounded-2xl px-5 py-5 flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-muted/20"
                >
                  <div>
                    <p className="text-[14px] font-semibold text-foreground mb-0.5">
                      Demo limit reached
                    </p>
                    <p className="text-[13px] text-muted-foreground leading-relaxed">
                      You&apos;ve experienced how Raise supports productive struggle. Ready to deploy this for your class?
                    </p>
                  </div>
                  <div className="flex items-center gap-2 shrink-0">
                    <button
                      onClick={reset}
                      className="text-[13px] font-medium text-muted-foreground hover:text-foreground transition-colors cursor-pointer flex items-center gap-1.5 whitespace-nowrap"
                    >
                      <RefreshCw className="h-3 w-3" />
                      Reset
                    </button>
                    <Button asChild size="sm" className="rounded-full h-8 px-4 text-[13px] font-semibold cursor-pointer">
                      <Link href="/signup">
                        Get access
                        <ArrowRight className="h-3 w-3 ml-1" />
                      </Link>
                    </Button>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>

            <div ref={messagesEndRef} className="h-2" />
          </div>
        )}

        {/* ── Input ─────────────────────────────────────────────────────── */}
        <div className={cn("sticky bottom-0 pb-5 pt-3 bg-background/80 backdrop-blur-xl", isEmpty && "mt-auto")}>
          <div className="absolute inset-x-0 -top-8 h-8 bg-gradient-to-t from-background to-transparent pointer-events-none" />

          <div
            className={cn(
              "relative rounded-xl border border-border bg-background transition-all duration-200",
              "focus-within:border-foreground/25 focus-within:shadow-[0_0_0_3px_rgba(0,0,0,0.04)]",
              "dark:focus-within:shadow-[0_0_0_3px_rgba(255,255,255,0.04)]",
              isLimitReached && "opacity-40 pointer-events-none select-none"
            )}
          >
            <Textarea
              aria-label="Ask Raise a physics question"
              ref={inputRef}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter" && !e.shiftKey) {
                  e.preventDefault();
                  handleSend(input);
                }
              }}
              placeholder={
                isLimitReached
                  ? "Demo limit reached"
                  : isEmpty
                  ? "Ask a physics question..."
                  : "Continue the conversation..."
              }
              className="w-full bg-transparent border-0 resize-none px-4 pt-3.5 pb-2 text-[14.5px] focus-visible:ring-0 focus-visible:ring-offset-0 placeholder:text-muted-foreground/40 min-h-[52px] max-h-[180px] leading-[1.6]"
              rows={1}
              disabled={isLimitReached || isTyping}
            />

            {/* Toolbar row */}
            <div className="flex items-center justify-between px-3 pb-3 pt-1">
              <div className="flex items-center gap-1.5 text-[11px] text-muted-foreground/40 select-none">
                <CornerDownLeft className="h-3 w-3" />
                <span>to send · Shift+Enter for new line</span>
              </div>
              <button
                type="button"
                onClick={() => handleSend(input)}
                disabled={!input.trim() || isLimitReached || isTyping}
                className={cn(
                  "h-7 w-7 rounded-lg flex items-center justify-center transition-all cursor-pointer",
                  input.trim() && !isLimitReached && !isTyping
                    ? "bg-foreground text-background hover:opacity-80 active:scale-95"
                    : "bg-muted text-muted-foreground/40 cursor-not-allowed"
                )}
              >
                <Send className="h-3.5 w-3.5" />
              </button>
            </div>
          </div>

          {/* Status row */}
          <div className="flex items-center justify-between mt-2 px-0.5">
            <p className="text-[11px] text-muted-foreground/40 font-medium">
              Raise · Socratic Learning · PhD-Verified
            </p>
            {isLimitReached ? (
              <button
                onClick={reset}
                className="text-[11px] text-muted-foreground/50 hover:text-muted-foreground transition-colors cursor-pointer flex items-center gap-1"
              >
                <RefreshCw className="h-2.5 w-2.5" />
                Reset session
              </button>
            ) : (
              <p className="text-[11px] text-muted-foreground/40">
                {questionsLeft} of {LIMIT} questions remaining
              </p>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";
import { authenticatedFetch } from "@/lib/authenticated-fetch";

import * as React from "react";
import { useState, useEffect, useRef } from "react";
import dynamic from "next/dynamic";
import { useAuth } from "@/contexts/auth-context";
import { db } from "@/lib/firebase";
import {
  doc,
  getDoc,
  setDoc,
  onSnapshot,
  updateDoc,
  serverTimestamp,
  collection,
  query,
  where,
  deleteDoc,
  increment
} from "firebase/firestore";
import { WorkspaceHeader } from "@/components/ui/workspace";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { ScrollArea } from "@/components/ui/scroll-area";
import { MarkdownRenderer } from "@/components/markdown-renderer";
import {
  Send,
  Loader2,
  Save,
  PenLine,
  Eye,
  Cpu,
  Trash2,
  Maximize2,
  BookMarked,
  Lock,
  Plus,
  MoreVertical,
  X,
  Crown,
  ZoomIn,
  ZoomOut,
  RotateCcw,
  Minimize2
} from "lucide-react";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger
} from "@/components/ui/dropdown-menu";

interface Notebook {
  id: string;
  title: string;
  content: string;
  studentId: string;
  createdAt: any;
  updatedAt: any;
}
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import TurndownService from "turndown";
import Showdown from "showdown";
import { ConfirmDialog } from "@/components/ui/confirm-dialog";
import { RaiseLogo } from "@/components/ui/raise-logo";

const turndown = new TurndownService();
const converter = new Showdown.Converter();

// Lazy load RichTextEditor to avoid SSR hydration issues
const RichTextEditor = dynamic(() => import("@/components/rich-text-editor").then(mod => mod.RichTextEditor), {
  ssr: false,
  loading: () => <div className="h-full w-full bg-muted animate-pulse flex items-center justify-center text-[10px] font-bold text-muted-foreground">Loading editor…</div>
});

interface Message {
  role: 'user' | 'assistant';
  content: string;
}

export default function NotebookPage() {
  const { user } = useAuth();
  const [notebooks, setNotebooks] = useState<Notebook[]>([]);
  const [activeNotebookId, setActiveNotebookId] = useState<string | null>(null);
  const [content, setContent] = useState("");
  const [title, setTitle] = useState("Untitled Notebook");
  const [isEditing, setIsEditing] = useState(true);
  const [editorMode, setEditorMode] = useState<'markdown' | 'rich-text'>('rich-text');
  const [notebookToDelete, setNotebookToDelete] = useState<string | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [lastSavedAt, setLastSavedAt] = useState<Date | null>(null);
  const [hasUnsavedChanges, setHasUnsavedChanges] = useState(false);
  const [isLocked, setIsLocked] = useState(false);
  const [orgData, setOrgData] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [studentUsage, setStudentUsage] = useState<number>(0);
  const [showCopilot, setShowCopilot] = useState(false);
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [zoomLevel, setZoomLevel] = useState(100);
  const [editingTitleId, setEditingTitleId] = useState<string | null>(null);

  // Use onSnapshot for real-time usage tracking from the user document
  useEffect(() => {
    if (!user) return;
    const unsubscribe = onSnapshot(doc(db, "users", user.uid), (doc) => {
      if (doc.exists()) {
        setStudentUsage(doc.data().aiUsageCount || 0);
      }
    });
    return () => unsubscribe();
  }, [user]);

  // AI is disabled IF:
  // 1. Organization has exhausted its budget (aiUsageCurrent >= aiBudgetLimit, with safety for 0 limits)
  // 2. Student has reached their personal monthly interaction limit
  const isAiDisabled =
    (orgData?.aiBudgetLimit > 0 && (orgData?.aiUsageCurrent || 0) >= (orgData?.aiBudgetLimit || 0)) ||
    (orgData?.aiNotebookLimitPerStudent > 0 && studentUsage >= (orgData?.aiNotebookLimitPerStudent || 0));

  // Helper to get HTML from Markdown
  const getHtml = (md: string) => converter.makeHtml(md);
  // Helper to get Markdown from HTML
  const getMarkdown = (html: string) => turndown.turndown(html);

  const scrollRef = useRef<HTMLDivElement>(null);
  const helpPanelRef = useRef<HTMLElement>(null);

  useEffect(() => {
    if (showCopilot && window.matchMedia("(max-width: 1279px)").matches) {
      helpPanelRef.current?.scrollIntoView({ block: "nearest" });
    }
  }, [showCopilot]);

  // Fetch List of Notebooks & Org Settings
  useEffect(() => {
    if (!user) return;

    // 1. Fetch Organization Data first for limits
    async function fetchOrgSettings() {
      try {
        const userDoc = await getDoc(doc(db, "users", user!.uid));
        const userData = userDoc.data();
        const orgId = userData?.organizationId;

        if (orgId) {
          // Use onSnapshot for real-time subscription status updates
          const unsubscribeOrg = onSnapshot(doc(db, "organizations", orgId), (orgSnap) => {
            if (orgSnap.exists()) {
              const data = orgSnap.data();
              setOrgData(data);
              if (data?.notebookLimit === 0) setIsLocked(true);
            }
          });
          return unsubscribeOrg;
        }
      } catch (err) {
        console.error("Access config failed:", err);
      }
    }

    const orgPromise = fetchOrgSettings();
    let orgUnsubscribe: (() => void) | undefined;
    orgPromise.then(unsub => { orgUnsubscribe = unsub; });

    // 2. Load Notebook List
    const q = query(collection(db, "notebooks"), where("studentId", "==", user.uid));
    const unsubscribe = onSnapshot(q, (snapshot) => {
      const handleSnapshot = async () => {
        let list = snapshot.docs.map(d => ({ id: d.id, ...d.data() } as Notebook));

        // Migration: Check if a notebook existed at notebooks/{uid} (the old structure)
        if (list.length === 0) {
          try {
            const oldRef = doc(db, "notebooks", user.uid);
            const oldSnap = await getDoc(oldRef);

            if (oldSnap.exists()) {
              const oldData = oldSnap.data();
              if (!oldData.studentId) {
                const newRef = doc(collection(db, "notebooks"));
                await setDoc(newRef, {
                  title: "Initial Notebook",
                  content: oldData.content || "",
                  studentId: user.uid,
                  createdAt: oldData.createdAt || serverTimestamp(),
                  updatedAt: oldData.updatedAt || serverTimestamp()
                });
                await updateDoc(oldRef, { studentId: user.uid, title: "Initial Notebook Migration" });
                return; // Re-fire listener
              }
            } else {
              // New user - create one
              const newRef = doc(collection(db, "notebooks"));
              await setDoc(newRef, {
                title: "My Research Notebook",
                content: "# Welcome\n\nCapture your thoughts here.",
                studentId: user.uid,
                createdAt: serverTimestamp(),
                updatedAt: serverTimestamp()
              });
              return; // Re-fire listener
            }
          } catch (err) {
            console.error("Migration/Setup error:", err);
            // Fallback: clear loading so user doesn't get stuck even if setup fails
            setLoading(false);
          }
        } else {
          setNotebooks(list);

          if (!activeNotebookId && list.length > 0) {
            setActiveNotebookId(list[0].id);
          }

          setLoading(false);
        }
      };

      handleSnapshot();
    }, (error) => {
      console.error("Snapshot error:", error);
      setLoading(false);
      toast.error("Cloud synchronization error.");
    });

    return () => {
      unsubscribe();
      if (orgUnsubscribe) orgUnsubscribe();
    };
  }, [user]);

  // Sync content and message history with active notebook
  useEffect(() => {
    if (!activeNotebookId || !user) return;

    const docRef = doc(db, "notebooks", activeNotebookId);
    const unsubscribe = onSnapshot(docRef, (docSnap) => {
      if (docSnap.exists()) {
        const data = docSnap.data();
        if (!hasUnsavedChanges) {
          setContent(data.content || "");
          setTitle(data.title || "Untitled");
          setLastSavedAt(data.updatedAt?.toDate() || null);
          // Load chat history from the notebook document
          if (data.messages && Array.isArray(data.messages)) {
            setMessages(data.messages);
          } else {
            setMessages([]);
          }
        }
      }
    });

    return () => unsubscribe();
  }, [activeNotebookId, hasUnsavedChanges]);

  // Auto-save logic
  useEffect(() => {
    if (!hasUnsavedChanges) return;

    const timeoutId = setTimeout(async () => {
      await saveNotebook();
    }, 3000);

    return () => clearTimeout(timeoutId);
  }, [hasUnsavedChanges, content, title]);

  const saveNotebook = async () => {
    if (!user || !activeNotebookId || !hasUnsavedChanges) return;

    setIsSaving(true);
    try {
      const docRef = doc(db, "notebooks", activeNotebookId);
      await updateDoc(docRef, {
        content: content,
        title: title,
        updatedAt: serverTimestamp()
      });
      setLastSavedAt(new Date());
      setHasUnsavedChanges(false);
    } catch (error) {
      console.error("Save failed:", error);
      toast.error("Sync failed.");
    } finally {
      setIsSaving(false);
    }
  };

  const createNewNotebook = async () => {
    if (!user || !orgData) return;

    const limit = orgData?.notebookLimitPerStudent || 1;
    if (notebooks.length >= limit) {
      toast.error(`Allowance exceeded. Limited to ${limit} notebooks.`);
      return;
    }

    try {
      const newRef = doc(collection(db, "notebooks"));
      await setDoc(newRef, {
        title: "New Notebook",
        content: "",
        studentId: user.uid,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp()
      });
      setActiveNotebookId(newRef.id);
      toast.success("New notebook initialized.");
    } catch (err) {
      toast.error("Notebook creation failed.");
    }
  };

  const deleteNotebook = async (id: string) => {
    if (!id || notebooks.length <= 1) {
      toast.error("At least one notebook is required.");
      return;
    }

    setNotebookToDelete(id);
  };

  const handleConfirmDelete = async () => {
    if (!notebookToDelete) return;

    try {
      await deleteDoc(doc(db, "notebooks", notebookToDelete));
      if (activeNotebookId === notebookToDelete) {
        const remaining = notebooks.filter(n => n.id !== notebookToDelete);
        setActiveNotebookId(remaining[0]?.id || null);
      }
      toast.success("Notebook erased.");
    } catch (err) {
      toast.error("Deletion failed.");
    } finally {
      setNotebookToDelete(null);
    }
  };

  const handleMarkdownChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const val = e.target.value;
    if (val !== content) {
      setContent(val);
      setHasUnsavedChanges(true);
    }
  };

  const handleRichTextChange = (html: string) => {
    const md = getMarkdown(html);
    if (md !== content) {
      setContent(md);
      setHasUnsavedChanges(true);
    }
  };

  const handleSendMessage = async () => {
    if (!inputValue.trim() || !user || isLoading) return;

    if (isAiDisabled) {
      toast.error(
        studentUsage >= (orgData?.aiNotebookLimitPerStudent || 0) && (orgData?.aiNotebookLimitPerStudent || 0) > 0
          ? "Monthly interaction limit reached. Contact your instructor to increase your quota."
          : "Network monthly AI budget reached."
      );
      return;
    }

    const userMessage: Message = { role: 'user', content: inputValue };
    const newMessages = [...messages, userMessage];
    setMessages(newMessages);
    setInputValue("");
    setIsLoading(true);

    // Also persist users's message to notebook right away
    if (activeNotebookId) {
      updateDoc(doc(db, "notebooks", activeNotebookId), {
        messages: newMessages,
        updatedAt: serverTimestamp()
      });
    }

    try {
      const response = await authenticatedFetch('/api/notebook/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          messages: newMessages,
          notebookContent: content,
          studentId: user.uid
        })
      });

      const data = await response.json();

      if (data.error) {
        toast.error(data.error);
        return;
      }

      setMessages(prev => {
        const updatedMessages = [...prev, { role: 'assistant' as const, content: data.content }];
        // Persist messages to the notebook document
        if (activeNotebookId) {
          const notebookRef = doc(db, "notebooks", activeNotebookId);
          updateDoc(notebookRef, {
            messages: updatedMessages,
            updatedAt: serverTimestamp()
          });
        }
        return updatedMessages;
      });

      // Persist usage count to Firestore
      if (user) {
        const userRef = doc(db, "users", user.uid);
        await updateDoc(userRef, {
          aiUsageCount: increment(1)
        });
      }
    } catch (error) {
      toast.error("Copilot connection severed.");
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isLoading]);

  if (isLocked) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[50dvh] space-y-6 text-center">
        <div className="p-6 bg-amber-50 dark:bg-amber-900/10 rounded-full">
          <Lock className="h-12 w-12 text-amber-500" />
        </div>
        <div className="max-w-md space-y-2">
          <h2 className="text-2xl font-black tracking-tight">Access Restricted</h2>
          <p className="text-sm text-muted-foreground font-medium leading-relaxed">
            Your instructor has not enabled Digital Notebook access for this network.
            Please contact your teacher to activate this researcher tool.
          </p>
        </div>
        <Button variant="outline" className="rounded-xl font-bold px-8 cursor-pointer" onClick={() => window.history.back()}>
          Return to Dashboard
        </Button>
      </div>
    );
  }

  return (
    <div className="space-y-5">

      {/* FULL SCREEN VIEWER OVERLAY */}
      {isFullScreen && !isEditing && (
        <div className="fixed inset-0 z-[100] bg-background  flex flex-col overflow-hidden">
          {/* FOCUS HEADER */}
          <div className="flex flex-wrap items-center justify-between gap-2 p-4 sm:px-6 border-b border-border bg-background  backdrop-blur-md z-10">
            <div className="flex min-w-0 items-center gap-2">
              <div className="p-2.5 bg-muted rounded-xl">
                <BookMarked className="h-5 w-5" />
              </div>
              <div>
                <h1 className="break-all text-lg font-semibold tracking-tight">{title}</h1>
                <p className="text-[10px] text-muted-foreground font-black uppercase tracking-widest">Focus view</p>
              </div>
            </div>

            <div className="flex items-center gap-3">
              <div className="flex items-center bg-muted p-1 rounded-full border border-border ">
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-8 w-8 rounded-full cursor-pointer"
                  aria-label="Zoom out"
                  onClick={() => setZoomLevel(prev => Math.max(50, prev - 10))}
                >
                  <ZoomOut className="h-4 w-4" />
                </Button>
                <div className="px-3 min-w-[60px] text-center">
                  <span className="text-[11px] font-black font-mono">{zoomLevel}%</span>
                </div>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-8 w-8 rounded-full cursor-pointer"
                  aria-label="Zoom in"
                  onClick={() => setZoomLevel(prev => Math.min(200, prev + 10))}
                >
                  <ZoomIn className="h-4 w-4" />
                </Button>
                <div className="w-px h-4 bg-muted mx-1" />
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-8 w-8 rounded-full cursor-pointer"
                  aria-label="Reset zoom"
                  onClick={() => setZoomLevel(100)}
                >
                  <RotateCcw className="h-3.5 w-3.5" />
                </Button>
              </div>

              <Button
                variant="outline"
                className="rounded-xl h-10 px-4 font-bold flex items-center gap-2 border-border hover:bg-accent  transition-all cursor-pointer"
                onClick={() => {
                  setIsFullScreen(false);
                  setZoomLevel(100);
                }}
              >
                <Minimize2 className="h-4 w-4" /> Exit focus
              </Button>
            </div>
          </div>

          {/* SCROLLABLE CONTENT */}
          <div className="flex-1 overflow-y-auto w-full custom-scrollbar scroll-smooth">
            <div className="min-h-full p-8 md:p-12 lg:p-20 flex justify-center">
              <div
                className="w-full max-w-4xl transition-all duration-200 origin-top"
                style={{ transform: `scale(${zoomLevel / 100})`, width: `${100 * (100 / zoomLevel)}%` }}
              >
                <div className="prose prose-lg dark:prose-invert max-w-none prose-headings:font-black prose-headings:tracking-tight prose-p:text-muted-foreground  prose-p:leading-relaxed prose-pre:bg-muted prose-pre:rounded-2xl pb-60">
                  <MarkdownRenderer noProse>{content}</MarkdownRenderer>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      <WorkspaceHeader title="Notebook" description="Keep class notes and review them in one place." />

      <div className="flex flex-wrap items-center justify-between gap-2">
        <div className="flex flex-wrap items-center gap-2">
          <Button variant="outline" size="sm" aria-pressed={!isEditing} onClick={() => setIsEditing(!isEditing)}>
            {isEditing ? <><Eye /> Preview</> : <><PenLine /> Edit notes</>}
          </Button>
          {isEditing ? (
            <Select value={editorMode} onValueChange={(value: "rich-text" | "markdown") => setEditorMode(value)}>
              <SelectTrigger size="sm" aria-label="Editor format"><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value="rich-text">Rich text</SelectItem>
                <SelectItem value="markdown">Markdown</SelectItem>
              </SelectContent>
            </Select>
          ) : (
            <Button variant="ghost" size="sm" onClick={() => setIsFullScreen(true)}>
              <Maximize2 /> Focus view
            </Button>
          )}
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <Button variant={showCopilot ? "secondary" : "outline"} size="sm" aria-pressed={showCopilot} onClick={() => setShowCopilot(!showCopilot)}>
            <RaiseLogo size={16} aria-hidden /> Raise help
          </Button>
          <Button size="sm" onClick={saveNotebook} disabled={!hasUnsavedChanges || isSaving}>
            <Save /> {isSaving ? "Saving…" : "Save"}
          </Button>
        </div>
      </div>

      <div className={cn("grid overflow-hidden rounded-xl border border-border bg-card lg:grid-cols-[12rem_minmax(0,1fr)]", showCopilot && "xl:grid-cols-[12rem_minmax(0,1fr)_18rem]")}>
        {/* NOTEBOOKS LIST PANEL */}
        <section aria-labelledby="notebook-library" className="flex min-w-0 flex-col border-b border-border lg:border-b-0 lg:border-r">
            <div className="p-4 border-b border-border flex items-center justify-between">
              <h2 id="notebook-library" className="text-sm font-medium">My notebooks</h2>
              <Button
                variant="ghost"
                size="icon"
                className="h-6 w-6 rounded-full hover:bg-accent  cursor-pointer"
                aria-label="New notebook"
                onClick={createNewNotebook}
              >
                <Plus className="h-3.5 w-3.5" />
              </Button>
            </div>
            <div className="max-h-36 overflow-y-auto lg:max-h-[54dvh]">
              <div className="p-2 space-y-1">
                {notebooks.map((nb) => (
                  <div
                    key={nb.id}
                    className={cn(
                      "group flex items-center justify-between rounded-lg border",
                      activeNotebookId === nb.id
                        ? "bg-background  border-border shadow-sm"
                        : "border-transparent hover:bg-accent text-muted-foreground"
                    )}
                  >
                    <div className="flex min-w-0 flex-1 items-center px-2">
