function FeatureCard({
	children,
	className,
	delay = 0,
}: {
	children: React.ReactNode;
	className?: string;
	delay?: number;
}) {
	const [isHovered, setIsHovered] = useState(false);
	const mouseX = useMotionValue(0);
	const mouseY = useMotionValue(0);

	function handleMouseMove({
		currentTarget,
		clientX,
		clientY,
	}: React.MouseEvent<HTMLDivElement>) {
		const { left, top } = currentTarget.getBoundingClientRect();
		mouseX.set(clientX - left);
		mouseY.set(clientY - top);
	}

	return (
		<motion.div
			onMouseMove={handleMouseMove}
			onMouseEnter={() => setIsHovered(true)}
			onMouseLeave={() => setIsHovered(false)}
			initial={{ opacity: 0, y: 20 }}
			whileInView={{ opacity: 1, y: 0 }}
			viewport={{ once: true }}
			transition={{ duration: 0.5, delay, ease: [0.16, 1, 0.3, 1] }}
			className={cn(
				"group relative overflow-hidden rounded-3xl border border-border/50 bg-white/70 dark:bg-card/50 backdrop-blur-xl px-8 pt-8 pb-6 hover:border-primary/40 hover:shadow-2xl hover:shadow-primary/10 hover:-translate-y-0.5 transition-all duration-500",
				className
			)}
		>
			<div className="pointer-events-none absolute inset-0 bg-[radial-gradient(rgba(0,0,0,0.15)_1px,transparent_1px)] dark:bg-[radial-gradient(rgba(255,255,255,0.25)_1px,transparent_1px)] [background-size:24px_24px] opacity-100" />

			{/* Light Mode Spotlight */}
			<motion.div
				className="pointer-events-none absolute -inset-px rounded-3xl opacity-0 transition-opacity duration-500 group-hover:opacity-100 z-0 dark:hidden"
				style={{
					background: useMotionTemplate`
						radial-gradient(
							400px circle at ${mouseX}px ${mouseY}px,
							rgba(0, 0, 0, 0.05),
							transparent 80%
						)
					`,
					opacity: isHovered ? 1 : 0,
				}}
			/>
			{/* Dark Mode Spotlight */}
			<motion.div
				className="pointer-events-none absolute -inset-px rounded-3xl opacity-0 transition-opacity duration-500 group-hover:opacity-100 z-0 hidden dark:block"
				style={{
					background: useMotionTemplate`
						radial-gradient(
							400px circle at ${mouseX}px ${mouseY}px,
							rgba(255, 255, 255, 0.1),
							transparent 80%
						)
					`,
					opacity: isHovered ? 1 : 0,
				}}
			/>
			{children}
		</motion.div>
	);
}

