  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { RundownDialog } from "@/components/ui/rundown-dialog";
import type { StudentPortfolio } from "@/lib/types";
